INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (321091, 14346, 'France 24', 'en', 'Solar eclipse 2026: Africa witnesses partial eclipse', 'https://www.france24.com/en/video/20260813-solar-eclipse-2026-africa-witnesses-partial-eclipse', 'Part of the world turned its eyes to the skies this Wednesday. The eclipse was also visible across Africa. In Tabarka, where the phenomenon was most pronounced in Tunisia, 59.06% of the Sun was obscured. The partial eclipse was also visible from Dakar and several regions of Senegal, with a maximum of around 37% of the Sun''s disk obscured towards the end of the day. And to make sure they didn''t miss the celestial event, our correspondents in Tunisia and Senegal also put on their special eclipse glasses.', 'https://s.france24.com/media/display/f271ad5c-9734-11f1-ad40-005056a90284/w:1024/p:16x9/EN-20260812-214658-215131-CS.jpg', '2026-08-13T16:55:03+00:00', '2026-08-13T22:50:55.826800'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
