INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349398, 14348, 'Aaj Tak', 'hi', 'रूस की सबसे अमीर महिला की कंपनी पर हमले, ₹58,600 करोड़ का झटका', 'https://www.aajtak.in/world/story/ukraine-russia-war-wildberries-drone-attacks-russia-largest-retailer-targeted-ntc-agkp-dskc-2623521-2026-08-17', 'रूस की सबसे बड़ी ऑनलाइन कंपनी वाइल्डबेरीज अब यूक्रेन के ड्रोन हमलों के निशाने पर है. मॉस्को के पास कंपनी का सबसे बड़ा गोदाम तबाह हो गया. यूक्रेन का आरोप है कि इस प्लेटफॉर्म से ड्रोन पुर्जे और सैन्य इस्तेमाल का सामान भी बिकता है, जिसे कंपनी नकारती है. अब तक कंपनी के 7 बड़े गोदाम तबाह हो चुके हैं और करीब 480 अरब रूबल का नुकसान हो चुका है.', '', '2026-08-16T20:20:03+00:00', '2026-08-16T21:59:50.908855'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
