INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329371, 14349, 'BBC News', 'en', 'Teens who fled Venezuela after deadly quakes caught in another disaster in Colombia', 'https://www.bbc.co.uk/news/articles/c9v42m3430vo', 'Deivi Delfín and his brother moved to Colombia after a quake in Venezuela killed their mother, but were caught in another deadly disaster.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/e44e/live/3a710840-979a-11f1-870d-5d08c49babb2.png', '2026-08-14T08:02:35+00:00', '2026-08-14T14:58:11.418923'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329515, 14349, 'Deutsche Welle', 'en', 'When the earth moves: 6 major earthquakes of 2026', 'https://www.dw.com/en/when-the-earth-moves-6-major-earthquakes-of-2026/a-78358208?maca=en-rss-en-world-4025-xml-mrss', 'Colombia, Venezuela, Mindanao: Thousands have died in powerful earthquakes this year. Six such events show that the magnitude of the quake isn''t the only factor determining the scale of the disaster.', '', '2026-08-13T17:17:00+00:00', '2026-08-14T14:58:32.784256'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329543, 14349, 'France 24', 'en', 'Colombia: Hundreds still missing as earthquake resue effort continues', 'https://www.france24.com/en/colombia-hundreds-still-missing-as-earthquake-resue-effort-continues', 'In Colombia hopes are fading of finding survivors after Monday’s powerful earthquake. Rescue teams are now turning their focus to recovering bodies, but families are still holding out hope of finding their loved ones alive beneath the rubble. Many have taken matters into their own hands, as our reporters found when they visited Cali, a city near the quake’s epicentre. A report by R. Sedano, M. Pluvinet, R. Pérez and Y. Royer.', 'https://s.france24.com/media/display/8711ec12-97ba-11f1-a9d0-005056a90284/w:1024/p:16x9/EN-20260814-091435-091645-CS.jpg', '2026-08-14T09:41:28+00:00', '2026-08-14T14:58:37.300537'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
