INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332391, 14349, 'The Japan Times', 'en', 'Hundreds still missing in Colombia as desperation grips earthquake rescue effort', 'https://www.japantimes.co.jp/news/2026/08/14/world/colombia-earthquake-missing-rescue-effort', 'Crews began shifting from a search-and-rescue effort to debris removal at many sites, a sign ​the disaster response was entering a grimmer phase after the crucial first 72 hours.', 'https://www.japantimes.co.jp/japantimes/uploads/images/2026/08/14/557248.JPG', '2026-08-14T03:08:00+00:00', '2026-08-14T15:03:39.813610'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332515, 14349, 'Euronews', 'en', 'Colombia earthquake: Dog rescued alive as 72-hour window closes', 'http://www.euronews.com/video/2026/08/14/colombia-earthquake-dog-rescued-alive-as-72-hour-window-closes', 'Colombia rescuers treated a dog pulled alive from earthquake rubble in Cali on Thursday, as emergency teams made a final push to find survivors before the critical 72-hour window closed.', '', '2026-08-14T09:49:58+00:00', '2026-08-14T15:03:49.881504'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
