INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (334865, 14351, 'The Times of India', 'en', 'Prichard Colon dies at 33: Anger grows after Terrel Williams’ account targeted', 'https://timesofindia.indiatimes.com/sports/international-sports/prichard-colon-dies-at-33-anger-grows-online-as-terrel-williams-alleged-instagram-account-is-targeted/articleshow/133248594.cms', 'Prichard Colon died at 33, nearly 11 years after his 2015 fight with Terrel Williams left him with a brain injury. Williams is facing online hate, including comments on an unverified Instagram account allegedly linked to him. He has expressed sorrow for Colon and said he prayed for him, but has not formally apologized or accepted blame for Colon’s injury.', 'https://static.toiimg.com/photo/msid-47529300.cms', '2026-08-14T17:26:20+00:00', '2026-08-14T18:09:03.408456'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
