INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349120, 14351, 'The Times of India', 'en', 'What happened to MLB legend Tommy John? Baseball icon dies at 83 after 26-year career', 'https://timesofindia.indiatimes.com/sports/mlb/news/what-happened-to-mlb-legend-tommy-john-baseball-icon-dies-at-83-after-26-year-career/articleshow/133279930.cms', 'What happened to Tommy John? The MLB legend died peacefully at 83 at his Florida home, surrounded by his family. Days earlier, he had been in hospice care and shared a farewell message with Yankees fans. John finished his 26-year career with 288 wins, but his greatest legacy came from returning to baseball after groundbreaking elbow surgery.', 'https://static.toiimg.com/photo/msid-47529300.cms', '2026-08-16T17:37:48+00:00', '2026-08-16T21:58:50.037125'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
